<?php
/** Proof — an activity's life (activities-reminders.md "Who may do what", activities-calendar.md §2–§3): schedule (the defaults: the account and
 * contact from the deal, the owner, the reminder), the refusals, update, Done with the outcome and THE NEXT-STEP PROMPT, reopen, snooze, reassign (the
 * new one told), participants, the edit rules, the wall, delete, the list's filters, the pickers. */
require __DIR__ . '/lib.php';
$x = run_tag();
$d = deal_make(26);
$deal = q('SELECT account_id, primary_contact_id FROM deals WHERE id = :d', ['d' => $d])[0];
echo "1. Schedule\n";
$since = last_activity_id();
$r = act(26, ['kind' => 'call', 'subject' => "Discovery $x", 'deal' => $d, 'starts_at' => at('+2 days 10:00')]);
$a = (int) ($r['json']['record_id'] ?? 0);
$row = act_row($a);
ok($r['code'] === 200 && $a > 0 && (int) $row['account_id'] === (int) $deal['account_id'] && (int) $row['contact_id'] === (int) $deal['primary_contact_id'] && (int) $row['owner_member_id'] === 26 && (int) $row['created_by'] === 26,
    'activity_create on a deal: the account and the primary contact follow, the caller does it');
ok((int) $row['remind_minutes_before'] === 30 && $row['remind_at'] !== null && $row['due_at'] === null && $row['starts_at'] !== null && $row['source'] === 'web', 'the default reminder (30 minutes, the settings\'), a call\'s start (not a due time), source web');
ok(str_contains((string) ($r['json']['location'] ?? ''), "/activities/$a") && str_contains((string) ($r['json']['refresh'] ?? ''), 'activityChanged'), 'it lands on the activity; activityChanged');
$log = activity('activity.create', $since)[0] ?? null;
$after = json_decode((string) ($log['after'] ?? '{}'), true);
ok($log !== null && (int) $log['deal_id'] === $d && (int) $log['account_id'] === (int) $deal['account_id'] && $after['subject'] === "Discovery $x" && !array_key_exists('body', $after), 'activity.create logged with the deal and the account, never the body');
ok((int) one('SELECT next_activity_id FROM deals WHERE id = :d', ['d' => $d]) === $a, 'the deal\'s next step is this call (the trigger)');
$m = act_id(26, ['kind' => 'meeting', 'subject' => "Meeting $x", 'deal' => $d, 'starts_at' => at('+3 days 14:00')]);
ok(str_starts_with(act_row($m)['ends_at'], gmdate('Y-m-d', strtotime('+3 days')) . ' 15:00'), 'a meeting without an end lasts an hour');
$t = act_id(26, ['kind' => 'task', 'subject' => "Bare task $x", 'due_at' => at('+1 day 09:00'), 'remind_minutes_before' => 'none', 'priority' => 'high', 'recurrence' => 'FREQ=WEEKLY']);
$tr = act_row($t);
ok($t > 0 && $tr['remind_minutes_before'] === null && $tr['remind_at'] === null && $tr['priority'] === 'high' && $tr['recurrence'] === 'FREQ=WEEKLY', 'a bare task stands alone; "none" means no reminder; priority; a weekly repeat');
ok(field_of(act(26, ['kind' => 'call', 'subject' => 'No record', 'starts_at' => at('+1 day')])) === 'deal', 'anything but a task names its record');
ok(field_of(act(26, ['kind' => 'call', 'deal' => $d, 'starts_at' => at('+1 day')])) === 'subject', 'a schedule needs a subject');
ok(field_of(act(26, ['kind' => 'call', 'subject' => 'When?', 'deal' => $d])) === 'starts_at' && field_of(act(26, ['kind' => 'task', 'subject' => 'When?'])) === 'due_at', '…and a time: a call\'s start, a task\'s due');
ok(field_of(act(26, ['kind' => 'meeting', 'subject' => 'Back', 'deal' => $d, 'starts_at' => at('+1 day 10:00'), 'ends_at' => at('+1 day 09:00')])) === 'ends_at', 'an end before the start is refused');
ok(field_of(act(26, ['kind' => 'call', 'subject' => 'Repeat', 'deal' => $d, 'starts_at' => at('+1 day'), 'recurrence' => 'FREQ=WEEKLY'])) === 'recurrence', 'only a task repeats');
ok(field_of(act(26, ['kind' => 'fax', 'subject' => 'x', 'deal' => $d, 'starts_at' => at('+1 day')])) === 'kind' && field_of(act(26, ['kind' => 'call', 'subject' => 'x', 'deal' => $d, 'starts_at' => 'tuesday'])) === 'starts_at', 'a kind and a time that are not ones');
$other = deal_make(30);
$acc30 = (int) one('SELECT account_id FROM deals WHERE id = :d', ['d' => $other]);
ok(field_of(act(26, ['kind' => 'call', 'subject' => 'Mixed', 'deal' => $d, 'account' => $acc30, 'starts_at' => at('+1 day')])) === 'account', 'a deal and another account: refused');
ok(act(29, ['kind' => 'task', 'subject' => 'Viewer', 'due_at' => at('+1 day')])['code'] === 403, 'a Viewer schedules nothing');
$tz = act_id(26, ['kind' => 'call', 'subject' => "Zone $x", 'deal' => $d, 'starts_at' => '2026-12-01T09:00', 'timezone' => 'America/New_York']);
ok(str_starts_with(act_row($tz)['starts_at'], '2026-12-01 14:00') && act_row($tz)['timezone'] === 'America/New_York', 'a time in a zone named: 09:00 New York is 14:00 UTC');
ok(field_of(act(26, ['kind' => 'call', 'subject' => 'x', 'deal' => $d, 'starts_at' => at('+1 day'), 'timezone' => 'Mars/Base'])) === 'timezone', 'a zone that is not one');
$ag = act_id(26, ['kind' => 'task', 'subject' => "For Marco $x", 'deal' => $d, 'due_at' => at('+1 day 12:00'), 'owner' => 27, 'participants' => (string) $deal['primary_contact_id'], 'members' => '28']);
ok((int) act_row($ag)['owner_member_id'] === 27 && (int) one("SELECT count(*) FROM notifications WHERE member_id = 27 AND kind = 'assigned' AND activity_id = :a", ['a' => $ag]) === 1, 'scheduled for someone else: theirs, and they are told');
ok((int) one('SELECT count(*) FROM activity_participants WHERE activity_id = :a', ['a' => $ag]) === 2, '…with a contact and a colleague taking part');

echo "2. Update and the rules\n";
$since = last_activity_id();
$r = post_as(26, '/activities/save.php', ['activity' => $a, 'subject' => "Discovery call $x", 'location' => 'Their office', 'body' => 'Secret words']);
$log = activity('activity.update', $since)[0] ?? null;
ok($r['code'] === 200 && act_row($a)['subject'] === "Discovery call $x" && act_row($a)['location'] === 'Their office' && act_row($a)['deal_id'] !== null, 'activity_update: the fields said; the rest stays');
ok($log !== null && !str_contains((string) $log['after'], 'Secret words') && str_contains((string) $log['after'], '(changed)'), 'activity.update logged; the body only as "(changed)"');
ok(post_as(30, '/activities/save.php', ['activity' => $a, 'subject' => 'Mine now'])['code'] === 403, 'another Rep may not change Priya\'s activity');
ok(post_as(27, '/activities/save.php', ['activity' => $a, 'priority' => 'low'])['code'] === 200, 'the manager may (activities.any)');
ok(post_as(26, '/activities/save.php', ['activity' => $a, 'remind_minutes_before' => 'none'])['code'] === 200 && act_row($a)['remind_at'] === null, 'the reminder taken off');
post_as(26, '/activities/save.php', ['activity' => $a, 'remind_minutes_before' => '15']);
ok((int) act_row($a)['remind_minutes_before'] === 15 && act_row($a)['remind_at'] !== null, '…and back at 15 minutes');
ok(get_as(26, "/activities/$a/edit")['code'] === 200 && get_as(30, "/activities/$a/edit")['code'] === 403, 'the edit form: Priya\'s, not another Rep\'s');
$priv = act_id(30, ['kind' => 'call', 'subject' => "Private $x", 'deal' => $other, 'starts_at' => at('+1 day')]);
pg_run("UPDATE activities SET is_private = true WHERE id = $priv");
ok(get_as(26, "/activities/$priv")['code'] === 404 && get_as(27, "/activities/$priv")['code'] === 200, 'another seller\'s private activity is a 404 to a Rep; the manager sees it');
pg_run("UPDATE deals SET restricted_to_member_id = 30 WHERE id = $other");
$walled = act_id(30, ['kind' => 'task', 'subject' => "Behind the wall $x", 'deal' => $other, 'due_at' => at('+1 day')]);
ok(get_as(26, "/activities/$walled")['code'] === 404 && get_as(26, "/activities/$walled/complete")['code'] === 404 && post_as(26, '/activities/complete.php', ['activity' => $walled])['code'] === 404,
    'an activity on a deal behind the wall: the same 404 for its page, Done and the post');
ok(act(26, ['kind' => 'call', 'subject' => 'x', 'deal' => $other, 'starts_at' => at('+1 day')])['json']['error']['fields']['deal'] === 'That deal is not here.', 'a deal behind the wall cannot be named');

echo "3. Done and the next step\n";
$d2 = deal_make(26);
$only = act_id(26, ['kind' => 'call', 'subject' => "Only step $x", 'deal' => $d2, 'starts_at' => at('+1 day 10:00')]);
$c = get_as(26, "/activities/$only/complete")['json']['data'] ?? [];
ok(($c['prompt_next_step'] ?? null) === true && ($c['default_outcome'] ?? '') === 'connected' && str_starts_with((string) ($c['next_subject'] ?? ''), 'Follow up with '), 'Done on the deal\'s only step: the prompt is on, the call\'s outcome first, "Follow up with <name>"');
ok(str_contains(html_as(26, "/activities/$only/complete")['body'], '<section class="card mb-3 border-primary" id="next-step-section">'), '…shown open on the page');
$second = act_id(26, ['kind' => 'task', 'subject' => "Second $x", 'deal' => $d2, 'due_at' => at('+5 days')]);
ok((get_as(26, "/activities/$only/complete")['json']['data']['prompt_next_step'] ?? null) === false && str_contains(html_as(26, "/activities/$only/complete")['body'], '<details class="card mb-3" id="next-step-section">'), 'another step planned: no prompt, the section folded');
post_as(26, '/records/delete.php', ['kind' => 'activity', 'record' => $second]);
$since = last_activity_id();
$r = post_as(26, '/activities/complete.php', ['activity' => $only, 'outcome' => 'left_message', 'outcome_note' => 'Voicemail', 'next_kind' => 'call', 'next_subject' => "Try again $x", 'next_at' => 'in3days']);
$next = (int) ($r['json']['next_activity_id'] ?? 0);
$o = act_row($only);
$n = act_row($next);
ok($r['code'] === 200 && $o['done_at'] !== null && $o['outcome'] === 'left_message' && (int) $o['done_by'] === 26 && $o['remind_at'] === null, 'activity_complete: done, the outcome, who did it; no reminder any more');
ok($next > 0 && $n['done_at'] === null && $n['subject'] === "Try again $x" && (int) $n['deal_id'] === $d2 && (int) $n['owner_member_id'] === 26 && str_starts_with($n['starts_at'], gmdate('Y-m-d', strtotime('+3 days')) . ' 10:00'),
    '…and the next step made in the same request: on the deal, Priya\'s, in three days at 10:00');
ok((int) one('SELECT next_activity_id FROM deals WHERE id = :d', ['d' => $d2]) === $next, 'the deal\'s next step is the new one (its card changes colour on the next poll)');
ok(count(activity('activity.complete', $since)) === 1 && (int) json_decode(activity('activity.complete', $since)[0]['after'], true)['next_activity_id'] === $next && count(activity('activity.create', $since)) === 1, 'activity.complete logged with the next step\'s id; the step\'s activity.create too');
ok(str_contains((string) $r['json']['location'], "next=$next"), 'it lands on the activity with a link to the next step');
ok(post_as(26, '/activities/complete.php', ['activity' => $only])['code'] === 422, 'Done twice: refused');
$plain = act_id(26, ['kind' => 'meeting', 'subject' => "Plain $x", 'deal' => $d2, 'starts_at' => at('+2 days 10:00')]);
post_as(26, '/activities/complete.php', ['activity' => $plain]);
ok(act_row($plain)['outcome'] === 'meeting_held', 'Done with no outcome: the kind\'s default (a meeting held)');
ok(field_of(post_as(26, '/activities/complete.php', ['activity' => $next, 'outcome' => 'meeting_held'])) === 'outcome', 'an outcome of another kind is refused');
ok(field_of(post_as(26, '/activities/complete.php', ['activity' => $next, 'next_kind' => 'call', 'next_subject' => 'x', 'next_at' => 'whenever'])) === 'next_at', 'a next step at no time is refused, nothing done');
ok(act_row($next)['done_at'] === null, '…the activity stays open');
ok(field_of(post_as(26, '/activities/complete.php', ['activity' => $next, 'done_at' => at('+2 days')])) === 'done_at', 'done in the future is refused');
ok(post_as(28, '/activities/complete.php', ['activity' => $ag])['code'] === 403, 'Bea, only taking part, may not complete Marco\'s task');
ok(post_as(27, '/activities/complete.php', ['activity' => $ag])['code'] === 200, 'Marco, who does it, may');
setting('next_step_prompt', 'false');
$d3 = deal_make(26);
$solo = act_id(26, ['kind' => 'call', 'subject' => "Solo $x", 'deal' => $d3, 'starts_at' => at('+1 day')]);
ok((get_as(26, "/activities/$solo/complete")['json']['data']['prompt_next_step'] ?? null) === false, 'the settings\' prompt off: no prompt');
setting('next_step_prompt', 'true');

echo "4. Reopen, reassign, participants, delete\n";
ok(post_as(26, '/activities/reopen.php', ['activity' => $only])['code'] === 200 && act_row($only)['done_at'] === null && act_row($only)['outcome'] === null, 'activity_reopen: open again, the outcome cleared');
ok(post_as(26, '/activities/reopen.php', ['activity' => $only])['code'] === 422, 'reopen an open one: refused');
$since = last_activity_id();
$r = post_as(26, '/activities/assign.php', ['activity' => $only, 'owner' => 30]);
ok($r['code'] === 200 && (int) act_row($only)['owner_member_id'] === 30 && (int) one("SELECT count(*) FROM notifications WHERE member_id = 30 AND kind = 'assigned' AND activity_id = :a", ['a' => $only]) === 1, 'activity_assign: Dana does it now, and she is told');
$al = activity('activity.assign', $since)[0] ?? null;
ok($al !== null && json_decode($al['before'], true)['owner_member_id'] === 26 && json_decode($al['after'], true)['owner_member_id'] === 30, 'activity.assign logged before → after');
ok(post_as(29, '/activities/assign.php', ['activity' => $only, 'owner' => 29])['code'] === 403, 'a Viewer reassigns nothing');
ok(post_as(26, '/activities/assign.php', ['activity' => $a, 'owner' => 40])['code'] === 200 && (int) one("SELECT count(*) FROM notifications WHERE member_id = 40 AND activity_id = :a", ['a' => $a]) === 0, 'given to an agent: no notification (its reminder is a dispatch)');
post_as(26, '/activities/assign.php', ['activity' => $a, 'owner' => 26]);
$con = (int) post_as(26, '/contacts/save.php', ['first_name' => 'Ola', 'last_name' => "Part $x"])['json']['record_id'];
$since = last_activity_id();
ok(post_as(26, '/activities/participants/add.php', ['activity' => $a, 'contact' => $con])['code'] === 200 && post_as(26, '/activities/participants/add.php', ['activity' => $a, 'member' => 27])['code'] === 200, 'activity_participant_add: a contact and a colleague');
ok(post_as(26, '/activities/participants/add.php', ['activity' => $a, 'contact' => $con])['json']['did'] === 'Ola Part ' . $x . ' takes part already', 'twice: nothing more, in words');
ok(field_of(post_as(26, '/activities/participants/add.php', ['activity' => $a])) === 'contact' && field_of(post_as(26, '/activities/participants/add.php', ['activity' => $a, 'member' => 40])) === 'member', 'one person, a contact or a colleague (an agent is not a colleague)');
$p = get_as(26, "/activities/$a")['json']['data']['activity']['participants'] ?? [];
ok(count($p) === 2 && in_array('Ola Part ' . $x, array_column($p, 'name'), true), 'get_activity lists them');
ok(post_as(26, '/activities/participants/remove.php', ['activity' => $a, 'contact' => $con])['code'] === 200 && post_as(26, '/activities/participants/remove.php', ['activity' => $a, 'contact' => $con])['code'] === 404, 'activity_participant_remove; a second time 404');
ok(count(activity('activity.participant_add', $since)) === 2 && count(activity('activity.participant_remove', $since)) === 1, 'both logged');
ok(post_as(30, '/activities/participants/add.php', ['activity' => $a, 'member' => 30])['code'] === 403, 'another Rep adds nobody to Priya\'s');
$gone = act_id(26, ['kind' => 'task', 'subject' => "Delete me $x", 'deal' => $d3, 'due_at' => at('+1 day')]);
ok(post_as(26, '/records/delete.php', ['kind' => 'activity', 'record' => $gone])['code'] === 200 && get_as(26, "/activities/$gone")['code'] === 404 && (int) one('SELECT next_activity_id FROM deals WHERE id = :d', ['d' => $d3]) === $solo, 'record_delete of an activity: gone; the deal\'s next step is the one left');

echo "5. The list\n";
$l = get_as(26, '/activities')['json']['data'];
$ids = array_column($l['rows'], 'activity_id');
ok(in_array($a, $ids, true) && !in_array($only, $ids, true) && !in_array($ag, $ids, true) && ($l['filters']['state'] ?? '') === 'open', 'mine and open by default (not Dana\'s now, not Marco\'s)');
$l = get_as(26, '/activities?state=done')['json']['data'];
ok(in_array($plain, array_column($l['rows'], 'activity_id'), true) && !in_array($a, array_column($l['rows'], 'activity_id'), true), 'state=done: the done ones');
$ov = act_id(26, ['kind' => 'task', 'subject' => "Late $x", 'deal' => $d3, 'due_at' => at('-3 days 10:00')]);
$l = get_as(26, '/activities?state=overdue')['json']['data'];
ok(in_array($ov, array_column($l['rows'], 'activity_id'), true) && !in_array($a, array_column($l['rows'], 'activity_id'), true), 'state=overdue');
$l = get_as(26, '/activities?state=all&kind=meeting')['json']['data'];
ok($l['rows'] !== [] && array_unique(array_column($l['rows'], 'kind')) === ['meeting'], 'kind=meeting');
$l = get_as(27, "/activities?deal=$d2&state=all")['json']['data'];
ok(count($l['rows']) >= 3 && array_unique(array_column($l['rows'], 'deal_id')) === [$d2] && ($l['filters']['who'] ?? '') === 'all', 'a deal named: everyone\'s on that deal');
$l = get_as(26, '/activities?q=' . rawurlencode("Late $x") . '&state=all')['json']['data'];
ok(count($l['rows']) === 1 && $l['rows'][0]['activity_id'] === $ov, 'words find the subject');
$l = get_as(27, '/activities?who=team:7&state=all')['json']['data'];
ok(in_array($a, array_column($l['rows'], 'activity_id'), true), 'who=team:7 (Sales) has Priya\'s');
$view = (int) one("SELECT id FROM saved_views WHERE system_key = 'my_today'");
$l = get_as(26, "/activities?view=$view")['json']['data'];
ok(($l['filters']['state'] ?? '') === 'today' && ($l['filters']['who'] ?? '') === 'me', 'the built-in "My activities today" runs as today, mine');
$h = html_as(26, '/activities')['body'];
ok(str_contains($h, 'id="activity-row-' . $a . '"') && str_contains($h, 'id="activity-row-' . $a . '-done"') && str_contains($h, 'id="activities-state-overdue"'), 'the list\'s HTML: a row each with Done, the state tabs');
ok(post_as(26, '/views/save.php', ['name' => "Calls $x", 'record_kind' => 'activity', 'filters' => ['owner' => 'me', 'when' => 'open', 'kind' => 'call']])['code'] === 200, 'Save this view of activities');

echo "6. The pickers\n";
$pick = static fn (string $q): array => (preg_match_all('/id="record-picker-row-(\d+)"/', html_as(26, '/pick/?' . $q, ['HX-Request: true'])['body'], $m) ? array_map('intval', $m[1]) : []);
ok(($pick('source=activity&q=' . rawurlencode("Discovery call $x"))[0] ?? 0) === $a, 'the activity picker finds it by subject');
ok(in_array(27, $pick('source=member&q=Marco'), true) && $pick('source=member&q=Expert') === [] && in_array(40, $pick('source=owner&q=Expert'), true), 'the colleague picker: people, never an agent (the owner picker has agents)');
finish();
